import type { Credentials } from '@opensteward/shared'
import { TOKEN_HELP_URL } from './constants'

/**
 * Planfix authenticates with a long-lived REST API token sent as
 * `Authorization: Bearer {token}`. The token is generated by the primary
 * account admin under Account Management → API Access → REST API; there is no
 * OAuth2 authorization-code flow for first-party API access.
 *
 * Credentials are collected through the Connect Link form (the `customForm`
 * helper wired up in `index.ts`):
 *   - `account` — the account subdomain (the `{name}` in
 *     `https://{name}.planfix.com`), or a full origin.
 *   - `apiKey`  — the REST API token.
 *
 * The token is stored as `accessToken`; the account is stored on
 * `credentials.extra.account` and used to build the per-account base URL.
 */

/** Connect Link form has no redirect URL — point users at the token docs. */
export function buildAuthUrl(_state: string): string {
  return TOKEN_HELP_URL
}

/** Planfix REST tokens are long-lived and do not refresh — return as-is. */
export async function refreshCredentials(credentials: Credentials): Promise<Credentials> {
  return credentials
}
